/* From Uiverse.io by omar-alghaish - Tags: loader */
.__UIV_SCOPE__ .loading {
  background-color: rgba(255, 0, 0, 0);
  align-items: center;
  justify-content: center;
  display: flex;
}

.__UIV_SCOPE__ .loading div {
  background-color: rgb(255, 217, 0);
  width: 20px;
  height: 20px;
  margin: 20px;
  border-radius: 50px;
  animation-name: load912355;
  animation-duration: .9s;
  animation-iteration-count: infinite;
  animation-direction: alternate;
  text-align: center;
  justify-content: center;
}

.__UIV_SCOPE__ .loading .a {
  animation-delay: .3s;
}

.__UIV_SCOPE__ .loading .u {
  animation-delay: .6s;
}

@keyframes load912355 {
  0% {
    transform: translateY(50px) scale(1);
  }

  100% {
    transform: translateY(10px) scale(1.8) rotate(360deg);
  }
}
